async function convertGroundingToCitations(groundingChunks, helpers) {
  const headers = {
    "Content-Type": "application/json",
    "User-Agent": "Tomi/1.0.1 (https://tomi.dev.lspm.io)",
  };
  const TIMEOUT = 3000;           // timeout cho helpers.httpRequest (mỗi bước redirect)
  const FALLBACK_TIMEOUT = 1500;  // timeout cho fetch dự phòng
  const MAX_REDIRECTS = 5;

  // Xử lý status giống code gốc: 404/403 -> null; 5xx (axios sẽ throw) -> null
  function isBadStatus(status) {
    return status === 404 || status === 403 || status >= 500;
  }

  // Cách 1: n8n helpers.httpRequest, tự theo dõi redirect để lấy URL cuối
  async function viaHttpRequest(url, method) {
    if (!helpers || typeof helpers.httpRequest !== 'function') {
      throw new Error('helpers.httpRequest not available');
    }
    let currentUrl = url;
    for (let hop = 0; hop <= MAX_REDIRECTS; hop++) {
      const res = await helpers.httpRequest({
        method,
        url: currentUrl,
        headers,
        timeout: TIMEOUT,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
        disableFollowRedirect: true,
      });
      const status = res.statusCode;
      const location = res.headers?.location;

      if (status >= 300 && status < 400 && location) {
        currentUrl = new URL(location, currentUrl).href;
        continue;
      }
      return isBadStatus(status) ? null : currentUrl;
    }
    // Quá số lần redirect cho phép: trả về URL cuối cùng đã biết
    return currentUrl;
  }

  // Cách 2: fetch dự phòng, tự follow redirect, lấy URL cuối qua res.url
  async function viaFetch(url, method) {
    if (typeof fetch !== 'function') {
      throw new Error('fetch not available');
    }
    const res = await fetch(url, {
      method,
      headers,
      redirect: 'follow',
      signal: AbortSignal.timeout(FALLBACK_TIMEOUT),
    });
    return isBadStatus(res.status) ? null : (res.url || url);
  }

  async function fetchUrlOnce(url, method) {
    console.log(`fetch [${method}] ${url}`);
    try {
      return await viaHttpRequest(url, method);
    } catch (err1) {
      console.log(`httpRequest failed for ${url}: ${err1.message || err1} -> fallback fetch`);
      try {
        return await viaFetch(url, method);
      } catch (err2) {
        console.log(`fetch failed for ${url}:`, err2.message || err2);
        return null;
      }
    }
  }

  async function fetchFinalUrl(url) {
    let finalUrl = await fetchUrlOnce(url, 'HEAD');
    if (!finalUrl) {
      finalUrl = await fetchUrlOnce(url, 'GET');
    }
    return finalUrl;
  }

  async function processChunk(idx, chunk) {
    const webInfo = chunk.web || {};
    const originalUrl = webInfo.uri || '';
    const title = webInfo.title || 'Unknown Source';

    if (!originalUrl) {
      return null;
    }

    const finalUrl = await fetchFinalUrl(originalUrl);

    if (finalUrl) {
      return {
        citation_index: idx,
        citation_url: finalUrl,
        citation_title: title,
      };
    }

    return {
      citation_index: idx,
      citation_url: title,
    };
  }

  const tasks = groundingChunks.map((chunk, idx) => processChunk(idx, chunk));
  const results = await Promise.all(tasks);
  console.log("result: " + JSON.stringify(results));
  return results.filter((res) => res);
}

// Thực thi chính trong n8n
const final = await convertGroundingToCitations($input.last().json.groundingChunks, this.helpers);
return {
  output: final
};
